import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const HEADER =
  '// Generated by @mobile-stack/design-tokens from tokens.json. Do not edit.'

export function hexToArgb(hex) {
  const match = /^#([0-9a-fA-F]{6})$/.exec(hex)
  if (!match) throw new Error(`Unsupported color "${hex}", expected #RRGGBB`)
  return `0xFF${match[1].toUpperCase()}`
}

function capitalize(name) {
  return name[0].toUpperCase() + name.slice(1)
}

export function renderSwift(tokens) {
  const colors = Object.entries(tokens.color)
    .map(([name, hex]) => `    static let ${name}: UInt32 = ${hexToArgb(hex)}`)
    .join('\n')
  const numbers = group =>
    Object.entries(tokens[group])
      .map(([name, value]) => `    static let ${name}: CGFloat = ${value}`)
      .join('\n')
  const typography = Object.entries(tokens.typography)
    .map(
      ([name, t]) =>
        `    static let ${name} = TypeToken(size: ${t.size}, lineHeight: ${t.lineHeight}, weight: ${t.weight})`,
    )
    .join('\n')
  const motion = Object.entries(tokens.motion)
    .map(
      ([name, ms]) =>
        `    static let ${name.replace(/Ms$/, '')}: TimeInterval = ${ms / 1000}`,
    )
    .join('\n')

  return `${HEADER}
// swiftformat:disable all
// swiftlint:disable all
import Foundation

struct TypeToken: Equatable {
    let size: CGFloat
    let lineHeight: CGFloat
    let weight: Int
}

enum ColorToken {
${colors}
}

enum Spacing {
${numbers('spacing')}
}

enum Radius {
${numbers('radius')}
}

enum TypeScale {
${typography}
}

enum Motion {
${motion}
}
`
}

export function renderKotlin(tokens, packageName) {
  const colors = Object.entries(tokens.color)
    .map(
      ([name, hex]) => `    val ${capitalize(name)} = Color(${hexToArgb(hex)})`,
    )
    .join('\n')
  const dps = group =>
    Object.entries(tokens[group])
      .map(([name, value]) => `    val ${capitalize(name)} = ${value}.dp`)
      .join('\n')
  const typography = Object.entries(tokens.typography)
    .map(
      ([name, t]) =>
        `    val ${capitalize(name)} = TypeToken(size = ${t.size}.sp, lineHeight = ${t.lineHeight}.sp, weight = ${t.weight})`,
    )
    .join('\n')
  const motion = Object.entries(tokens.motion)
    .map(([name, ms]) => `    const val ${capitalize(name)} = ${ms}`)
    .join('\n')

  return `${HEADER}
@file:Suppress("all")

package ${packageName}

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.unit.TextUnit
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp

data class TypeToken(val size: TextUnit, val lineHeight: TextUnit, val weight: Int)

object ColorToken {
${colors}
}

object Spacing {
${dps('spacing')}
}

object Radius {
${dps('radius')}
}

object TypeScale {
${typography}
}

object Motion {
${motion}
}
`
}

const here = dirname(fileURLToPath(import.meta.url))

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const tokens = JSON.parse(readFileSync(join(here, 'tokens.json'), 'utf8'))
  const dist = join(here, 'dist')
  mkdirSync(dist, { recursive: true })
  writeFileSync(join(dist, 'Tokens.generated.swift'), renderSwift(tokens))
  writeFileSync(
    join(dist, 'Tokens.kt'),
    renderKotlin(tokens, 'com.example.mobilestack.designsystem.generated'),
  )
  console.log(
    'design-tokens: wrote dist/Tokens.generated.swift, dist/Tokens.kt',
  )
}
